    if profile == "default" {
        components.extend(
            RUST_DEFAULT_PROFILE_COMPONENTS
                .iter()
                .map(|component| (*component).to_string()),
        );
    }
    Some(RustupProfileComponents {
        components,
        host: String::new(),
    })
}

