#[derive(Debug, Clone, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub(crate) enum EnvValue {
    String(String),
    Integer(i64),
    Boolean(bool),
}

impl EnvValue {
    pub(crate) fn into_string(self) -> Option<String> {
        match self {
            Self::String(value) => Some(value),
            Self::Integer(value) => Some(value.to_string()),
            Self::Boolean(true) => Some("true".to_string()),
            Self::Boolean(false) => None,
        }
    }

    pub(crate) fn into_default_string(self) -> Option<String> {
        match self {
            Self::String(value) => Some(value),
            Self::Integer(value) => Some(value.to_string()),
            Self::Boolean(_) => None,
        }
    }
}

impl TryFrom<&toml::Value> for EnvValue {
    type Error = String;

    fn try_from(value: &toml::Value) -> Result<Self, Self::Error> {
        match value {
            toml::Value::String(value) => Ok(Self::String(value.clone())),
            toml::Value::Integer(value) => Ok(Self::Integer(*value)),
            toml::Value::Boolean(value) => Ok(Self::Boolean(*value)),
            _ => Err("environment values must be strings, integers, or booleans".to_string()),
        }
    }
}

impl From<String> for EnvValue {
        ToolVersion {
            request,
            version,
            before_date: None,
            locked: false,
            resolved_from_lockfile: false,
            lock_platforms: Default::default(),
            install_path: None,
            install_path_is_exact: false,
            install_path_is_explicit: false,
            conda_packages: Default::default(),
            pkgx_packages: Default::default(),
            install_satisfied: None,
        }
    }

    pub(crate) async fn resolve(
        config: &Arc<Config>,
        request: ToolRequest,
        opts: &ResolveOptions,
    ) -> Result<Self> {
        let install_env = request.options().core.install_env;
        crate::env::with_install_env(install_env, Self::resolve_(config, request, opts)).await
    }

    async fn resolve_(
        config: &Arc<Config>,
        request: ToolRequest,
        opts: &ResolveOptions,
    ) -> Result<Self> {
        let minimum_release_age = request.options().minimum_release_age().map(str::to_string);
        let mut opts = opts.clone();
        opts.apply_before_date_for_tool(request.ba(), minimum_release_age.as_deref())?;
