    pub(crate) fn get_text_request<U: IntoUrl>(&self, url: U) -> TextRequest<'_> {
        // Defer surfacing an invalid URL to `send()` (which returns `Result`) so a
        // bad URL is reported as an error instead of panicking here. See #3547.
        TextRequest {
            client: self,
            url: url.into_url().map_err(|e| e.to_string()),
            extra_headers: HeaderMap::new(),
            retries: Settings::get().http_retries(),
        }
    }

    /// Like get_text but caches results in memory for the duration of the process.
    /// Useful when the same URL will be requested multiple times (e.g., SHASUMS256.txt
    /// when locking multiple platforms). Concurrent requests for the same URL will
    /// wait for the first fetch to complete.
    pub(crate) async fn get_text_cached<U: IntoUrl>(&self, url: U) -> Result<String> {
        let url = url.into_url()?;
        let key = url.to_string();

        // Get or create the OnceCell for this URL
        let cell = {
            let mut cache = HTTP_CACHE.lock().unwrap();
            cache.entry(key).or_default().clone()
        };

        // Initialize the cell if needed - concurrent callers will wait
        let result = cell
            .get_or_init(|| {
                let url = url.clone();
                async move {
                    match self.get_text(url).await {
                        Ok(text) => Ok(text),
                        Err(err) => Err(err.to_string()),
                    }
                }
            })
            .await;

        let profile = String::from_utf8_lossy(&output.stdout).trim().to_string();
        if profile.is_empty() {
            bail!(
                "rustup show profile returned an empty profile for {}",
                tv.style()
            );
        }
        Ok(profile)
    }

    fn rustup_toolchain_manifest(
        &self,
        tv: &ToolVersion,
        runtime: &RustRuntime,
    ) -> Result<Option<InstalledRustupManifest>> {
        let args = vec!["show".to_string(), "active-toolchain".to_string()];
        let mut cmd = cmd(runtime.bin_dir.join(RUSTUP_BIN), args)
            .env("PATH", rustup_path_env(runtime)?)
            .stdout_capture()
            .stderr_capture()
            .unchecked();
        for (key, value) in rustup_env(&runtime.homes, &tv.version) {
            cmd = cmd.env(key, value);
        }
        let output = match cmd.run() {
            Ok(output) if output.status.success() => output,
            Ok(output) => {
                debug!(
                    "rustup show active-toolchain failed for {}: {}",
                    tv.style(),
                    String::from_utf8_lossy(&output.stderr).trim()
                );
                return Ok(None);
            }
            Err(err) => {
                debug!(
                    "rustup show active-toolchain failed for {}: {err:#}",
                    tv.style()
                );
                return Ok(None);
            }
        };
        let output = String::from_utf8_lossy(&output.stdout);
        let Some(toolchain) = output.split_whitespace().next() else {
            debug!(
                "rustup show active-toolchain returned no toolchain for {}",
                tv.style()
            );
            return Ok(None);
        };
        let manifest = runtime
            .homes
            .rustup
            .join("toolchains")
            .join(toolchain)
            .join("lib")
            .join("rustlib")
            .join("multirust-channel-manifest.toml");
        if !manifest.is_file() {
            debug!(
                "rustup manifest missing for {} at {}",
                tv.style(),
                manifest.display()
            );
            return Ok(Some(InstalledRustupManifest {
                toolchain: toolchain.to_string(),
                contents: None,
            }));
        }
        let contents = match file::read_to_string(&manifest) {
            Ok(contents) => Some(contents),
            Err(err) => {
                debug!(
                    "failed to read rustup manifest for {} at {}: {err:#}",
                    tv.style(),
                    manifest.display()
                );
                None
            }
        };
        Ok(Some(InstalledRustupManifest {
            toolchain: toolchain.to_string(),
            contents,
        }))
    }

    fn rustup_profile_components(
        &self,
        tv: &ToolVersion,
        profile: &str,
        runtime: &RustRuntime,
    ) -> Result<Option<RustupProfileComponents>> {
        let profile = normalize_rustup_profile(profile)?;
        let Some(installed) = self.rustup_toolchain_manifest(tv, runtime)? else {
            return Ok(fallback_rustup_profile_components(profile));
        };
        if let Some(manifest) = installed.contents {
            match parse_rustup_profile_components(&manifest, &installed.toolchain, profile) {
                Ok(components) => return Ok(Some(components)),
                Err(err) => debug!(
                    "failed to resolve rustup {profile} profile for {} from its installed manifest: {err:#}",
                    tv.style()
                ),
            }
        }
        if profile == "complete" {
            bail!(
                "cannot reconcile the rustup complete profile for {} because its installed manifest is unusable",
                tv.style()
            );
        }
        Ok(fallback_rustup_profile_components(profile))
    }

    fn missing_components(
        &self,
        requested: &[String],
        installed: &BTreeSet<String>,
        host: Option<&str>,
    ) -> Vec<String> {
        requested
            .iter()
            .filter(|component| !rustup_component_installed(installed, component, host))
            .cloned()
            .collect()
    }

    fn missing_targets(&self, requested: &[String], installed: &BTreeSet<String>) -> Vec<String> {
        requested
            .iter()
            .filter(|target| !installed.contains(*target))
            .cloned()
            .collect()
    }
}

